svg.script:
const f=document.getElementById("frame");let p=new URL("./index.html",document.baseURI),l=false;
function e(x){console.error(x);const s=String(x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");f.srcdoc=`<!doctype html><html><head><meta charset="utf-8"><style>body{background:#111;color:white;font-family:system-ui,sans-serif;padding:30px}pre{color:#ff7777;white-space:pre-wrap}</style></head><body><h1>Failed to load page</h1><pre>${s}</pre></body></html>`}
function b(u){const x=new URL(u,p);x.searchParams.set("__nc",Date.now()+"_"+Math.random().toString(36).slice(2));return x.href}
function q(d,u){const n=Date.now()+"_"+Math.random().toString(36).slice(2);d.querySelectorAll("script[src],link[href],img[src],source[src],audio[src],video[src],iframe[src],embed[src],object[data],input[src]").forEach(a=>{const k=a.hasAttribute("src")?"src":a.hasAttribute("href")?"href":a.hasAttribute("data")?"data":null;if(!k)return;const v=a.getAttribute(k);if(!v||/^(data:|blob:|javascript:|mailto:|tel:|#)/i.test(v))return;try{const z=new URL(v,u);z.searchParams.set("__nc",n);a.setAttribute(k,z.href)}catch{}})}
function h(d,u){const s=d.createElement("script");s.textContent=`(()=>{const N=u=>{try{const x=new URL(u,document.baseURI);if(!/^(data:|blob:|javascript:|mailto:|tel:)/i.test(x.protocol)){x.searchParams.set('__nc',Date.now()+'_'+Math.random().toString(36).slice(2));return x.href}}catch(e){}return u};const F=window.fetch;window.fetch=function(i,o){o=Object.assign({},o,{cache:'no-store'});if(typeof i==='string'||i instanceof URL)i=N(i);else if(i instanceof Request)i=new Request(N(i.url),i);return F.call(this,i,o)};const O=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,u,...r){return O.call(this,m,N(u),...r)};})();`;d.head.prepend(s)}
async function g(u){try{const x=new URL(u,p),r=await fetch(b(x.href),{cache:"no-store"});if(!r.ok)throw new Error("HTTP "+r.status+" while loading "+x.href);const t=await r.text(),d=new DOMParser().parseFromString(t,"text/html");if(!d.head){const a=d.createElement("head");d.documentElement.prepend(a)}const a=d.querySelector("base[href]");if(a)a.href=new URL(a.getAttribute("href"),x).href;else{const a=d.createElement("base");a.href=new URL("./",x).href;d.head.prepend(a)}q(d,x);h(d,x);p=x;f.srcdoc="<!doctype html>\n"+d.documentElement.outerHTML}catch(x){e(x)}}
f.addEventListener("load",function(){if(l)return;l=true;try{const d=f.contentDocument;if(!d){l=false;return}d.addEventListener("click",function(e){const a=e.target.closest&&e.target.closest("a");if(!a)return;const h=a.getAttribute("href");if(!h||h.startsWith("#")||h.startsWith("javascript:")||h.startsWith("mailto:")||h.startsWith("tel:")||a.target==="_blank")return;let u;try{u=new URL(h,p)}catch{return}if(u.origin!==p.origin)return;const n=u.pathname.toLowerCase();if(n.endsWith(".html")||n.endsWith(".htm")||n.endsWith("/")){e.preventDefault();g(u.href)}},true)}catch(x){console.error("Couldn't install navigation handler:",x)}l=false});
g(p.href);
